import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"可观测性","description":"","frontmatter":{"title":"可观测性","order":50},"headers":[],"relativePath":"sde/sre/elk.md","filePath":"sde/sre/elk.md"}`),a={name:`sde/sre/elk.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="可观测性-监控、日志与链路追踪" tabindex="-1">可观测性：监控、日志与链路追踪 <a class="header-anchor" href="#可观测性-监控、日志与链路追踪" aria-label="Permalink to “可观测性：监控、日志与链路追踪”">​</a></h1><p>可观测性（Observability）回答的问题是：<strong>通过系统的外部输出，能多大程度推断系统内部的状态</strong>。传统的监控（Monitoring）回答&quot;系统是否正常&quot;——预定义的指标和阈值告诉你红灯还是绿灯。可观测性回答&quot;系统为什么不正常&quot;——在没有预想到的故障发生时，能否通过既有数据定位根因。</p><p>三根支柱构成可观测性的数据模型：<strong>指标</strong>（Metrics，随时间变化的数值）、<strong>日志</strong>（Logs，离散事件的文本记录）、<strong>链路追踪</strong>（Traces，请求穿越多个服务的时间线）。三者各有不可替代的视角，也有明确的关联机制。</p><h2 id="指标-低成本的全局视野" tabindex="-1">指标：低成本的全局视野 <a class="header-anchor" href="#指标-低成本的全局视野" aria-label="Permalink to “指标：低成本的全局视野”">​</a></h2><p>指标是聚合的数值——QPS、P99 延迟、错误率、内存使用量。它的优势是<strong>存储成本低</strong>（一个时间序列每分钟一个数据点，一年不过 50 万个点）和<strong>查询速度快</strong>（聚合查询在预计算的序列上执行）。这使指标适合回答&quot;系统的整体健康状态&quot;和&quot;趋势变化&quot;。</p><p>指标的设计核心是<strong>维度（labels）</strong>。Prometheus 的数据模型是多维时间序列——<code>http_requests_total{method=&quot;GET&quot;, path=&quot;/api/users&quot;, status=&quot;500&quot;}</code> 的每个 label 组合是一条独立序列。维度设计的好坏直接决定排查能力：有 status 维度能立刻看到错误率飙升，有 path 维度能定位到具体接口，缺失维度则只能知道&quot;出了问题&quot;但不知道哪里出的问题。工程实践中的准则：高基数维度（user_id、request_id）<strong>不要</strong>放进指标 label——每个唯一值产生一条序列，基数爆炸会拖垮存储；这类信息属于日志和追踪的领域。</p><p><strong>Prometheus</strong> 是指标领域的事实标准。Pull 模型（Prometheus 主动抓取 exporter 暴露的 <code>/metrics</code> 端点）、PromQL 查询语言、告警规则（Alertmanager）构成完整的指标闭环。长期存储（Prometheus 本地存储有限）通过 Thanos 或 VictoriaMetrics 扩展。</p><div class="language-promql"><button title="Copy Code" class="copy"></button><span class="lang">promql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 过去 5 分钟的错误率，按 path 分组</span></span>
<span class="line"><span>sum(rate(http_requests_total{status=~&quot;5..&quot;}[5m])) by (path)</span></span>
<span class="line"><span>  / sum(rate(http_requests_total[5m])) by (path)</span></span></code></pre></div><h2 id="日志-事件的全量记录" tabindex="-1">日志：事件的全量记录 <a class="header-anchor" href="#日志-事件的全量记录" aria-label="Permalink to “日志：事件的全量记录”">​</a></h2><p>日志记录离散事件——一个请求的完整上下文、一个错误的堆栈、一次状态变更。与指标相反，日志的<strong>存储成本高</strong>（一条结构化日志几百字节到几 KB）但<strong>信息量大</strong>（可以包含任意上下文字段）。</p><p>结构化日志是现代实践的分水线。传统的非结构化日志（<code>Connection failed for user 123 at 2026-08-14 10:23:45</code>）对机器解析不友好——grep 能用但聚合分析困难。结构化日志（<code>{&quot;event&quot;: &quot;connection_failed&quot;, &quot;user_id&quot;: 123, &quot;error&quot;: &quot;timeout&quot;}</code>）支持字段级查询和聚合。日志框架的结构化输出（JSON formatter）+ 采集端的字段解析 + 存储端的全文索引构成结构化日志管线。</p><p><strong>ELK/EFK 栈</strong>（Elasticsearch + Logstash/Filebeat + Kibana）是日志领域的传统方案：Filebeat 采集 → Logstash 解析富化 → Elasticsearch 索引 → Kibana 查询可视化。<strong>Loki</strong>（Grafana 生态）是轻量替代——只索引 label 不索引全文，存储成本降一个数量级，代价是全文搜索能力弱（依赖 LogQL 的标签过滤 + 受限的行过滤）。选型分界：需要复杂全文搜索和长期留存选 ELK，只需要按服务/级别/trace_id 过滤查看选 Loki。</p><h2 id="链路追踪-请求的时空之旅" tabindex="-1">链路追踪：请求的时空之旅 <a class="header-anchor" href="#链路追踪-请求的时空之旅" aria-label="Permalink to “链路追踪：请求的时空之旅”">​</a></h2><p>分布式系统中一个请求穿越多个服务——网关 → 用户服务 → 订单服务 → 数据库。每个服务各自记录日志，但&quot;这些日志属于同一个请求&quot;的关联信息缺失。链路追踪补上这块：每个请求携带全局唯一的 <strong>trace_id</strong>，每经过一个服务产生一个 <strong>span</strong>（有开始/结束时间和操作名），所有 span 通过 trace_id 关联成一棵调用树。</p><p>追踪的核心价值是<strong>延迟归因</strong>。用户报&quot;下单慢&quot;，从 trace 树上立刻看到：网关 5ms → 用户服务 10ms → 订单服务 800ms → 其中数据库查询 750ms。瓶颈定位从&quot;逐个服务查日志&quot;变成&quot;看一棵树&quot;。这在调用链超过 3 层的系统中几乎是唯一高效的排障手段。</p><p><strong>OpenTelemetry</strong>（OTel）是三支柱的统一采集标准——SDK（各语言的应用内埋点）、Collector（接收/处理/导出的中间层）、OTLP 协议（SDK 到 Collector 的传输）。OTel 的意义是解耦：应用只对接 OTel SDK，后端（Jaeger、Zipkin、Prometheus、Loki、商业 APM）可以随时替换——避免了被单一可观测厂商锁定。</p><p>追踪的采样策略是成本与覆盖的权衡。全量追踪（每个请求都记录）在小流量系统可行，高流量系统通常采样（1%-10%）——但纯随机采样会错过低频但关键的错误请求。自适应采样（错误请求必采、慢请求高概率采、正常请求低概率采）是现代后端的标准能力。</p><h2 id="三支柱的关联" tabindex="-1">三支柱的关联 <a class="header-anchor" href="#三支柱的关联" aria-label="Permalink to “三支柱的关联”">​</a></h2><p>三支柱不是孤立的——关联机制决定它们的组合价值：</p><p><strong>Exemplars</strong>（样本关联）：指标的数据点附带一个 exemplar——指向该数据点来源的具体 trace。P99 延迟图上的异常点，点击 exemplar 直接跳转到对应的慢请求 trace——从&quot;指标发现异常&quot;到&quot;追踪定位原因&quot;的桥。</p><p><strong>trace_id in logs</strong>：日志中注入 trace_id 字段——从 trace 树发现订单服务的数据库查询慢，用 trace_id 查日志看到该请求的完整参数和 SQL。指标 → 追踪 → 日志的排障链路就此贯通。</p><p><strong>统一元数据</strong>：服务名、环境（prod/staging）、版本号在三支柱中保持一致的 label/tag/字段——这是跨支柱查询（&quot;过滤出 v2.3.1 版本的所有数据&quot;）的前提。</p><p>OpenTelemetry 的 Collector 通常承担关联的实现——接收三支柱数据后统一注入服务元数据，再分发到各自的后端。</p><h2 id="实践路径" tabindex="-1">实践路径 <a class="header-anchor" href="#实践路径" aria-label="Permalink to “实践路径”">​</a></h2><p>可观测性建设的一个务实顺序：先有<strong>指标</strong>（Prometheus + Grafana，覆盖 RED 方法——Rate/Error/Duration——每个服务的三个基础指标），这是发现问题的眼睛。再有<strong>结构化日志</strong>（集中收集 + trace_id 注入），这是定位问题的第一层。最后是<strong>追踪</strong>（OTel SDK 埋点 + Jaeger/Tempo 后端），这是复杂调用链的终极武器。三者的投入比大约是 3:4:3——指标和追踪的基础设施成本高（存储和查询），日志的采集成本高（量大）。</p><p>告警是可观测性的出口。好的告警实践：基于症状而非原因告警（用户可感知的错误率/延迟，而非 CPU 使用率——原因类指标波动频繁且用户无感）；分级（page 立即处理 vs ticket 工作时间处理）；每个告警有 runbook（接警后的处理步骤文档）——没有 runbook 的告警只是噪音的另一种形态。</p>`,26)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};